/**
 * Rules the UI listener (`uiRequestHandler` in packages/cli) and the web
 * service worker (`src-ui/public/sw.js`, generated by
 * `scripts/vite-offline-shell.ts`) must agree on. The worker is plain script
 * served from the UI root, so the build injects these values into it rather
 * than the worker importing this module.
 */

/**
 * A content-hashed build asset, relative to the UI root without a leading
 * slash. The listener serves a match with `immutable` caching, and the worker
 * keeps a cache-first copy of it, so the two can never disagree about which
 * files are safe to reuse across reloads.
 */
export const UI_IMMUTABLE_ASSET_PATTERN =
  /^assets\/(?:[\w-]+\/)*[\w.-]+-[A-Za-z0-9_-]{8,}\.[\w]+$/;

/**
 * The document Content-Security-Policy. The listener passes the per-request
 * script nonce it injects; the offline fallback shell has no inline script and
 * omits it, so the same policy otherwise applies offline.
 */
export function uiDocumentContentSecurityPolicy(scriptNonce?: string): string {
  return [
    "default-src 'none'",
    `script-src 'self'${scriptNonce ? ` 'nonce-${scriptNonce}'` : ''} 'wasm-unsafe-eval'`,
    // Fonts are self-hosted (#2648) — no external font origins.
    "style-src 'self' 'unsafe-inline'",
    "font-src 'self' data:",
    "img-src 'self' data: blob:",
    "media-src 'self' blob:",
    "connect-src 'self' http: https: ws: wss:",
    "frame-src 'self' blob: http: https:",
    "worker-src 'self' blob:",
    "manifest-src 'self'",
    "object-src 'none'",
    "base-uri 'none'",
    "frame-ancestors 'none'",
    "form-action 'self'",
  ].join('; ');
}
